* calculate equity vesting variables from Equilar;
* input data: equilar data;
* Interest rate from FRED; 
* All other inputs such as WRDS Compustat/CRSP/Thomson Financial Insider Trading are specified in the code;

LIBNAME v "[redacted-path-4789d730104d]";

%MACRO read_company_financials;
	%DO year = 2006 %TO 2016;
		PROC IMPORT DATAFILE = "[redacted-path-b8bd76a092ed]" 
			OUT = cf_&year 
			DBMS = EXCELCS
			REPLACE; 
			SHEET = "Company Financials";

* read in CUSIP;
PROC IMPORT DATAFILE = "[redacted-path-6a4f4716fd98]" 
	OUT = cusips 
	DBMS = EXCELCS
	REPLACE; 
	SHEET = "CUSIPs";
RUN;
PROC SORT DATA = cusips NODUPKEY; BY company_id; RUN;

PROC SQL;
	CREATE TABLE cf2 AS
	SELECT	a.*, b.cusip
	FROM	cf (DROP = cusip) a, cusips b
	WHERE	a.company_id = b.company_id;
QUIT;

* Read in Executive Data - ND;
%MACRO read_ednd;
	%DO year = 2006 %TO 2016;
		PROC IMPORT DATAFILE = "[redacted-path-b8bd76a092ed]" 
			OUT = ednd_&year 
			DBMS = EXCELCS
			REPLACE; 
			SHEET = "Executive Data - ND";
		RUN;
		DATA ednd_&year;
			SET ednd_&year;
			equilarfyear = &year;
			fyear = YEAR(fy_end) - (MONTH(fy_end) <= 5);
			FORMAT FY_End Resignation_Date MMDDYY10.;
			DROP _ _1 _2 _3 _4 _5 _6 _7;
			WHERE company ^= '' AND executive_id ^= '99999.9.N.99999';
		RUN;
	%END;

	DATA ednd; 
		SET ednd_2015-ednd_2016 ednd_2006-ednd_2014; 
		executive_id2 = SCAN(executive_id, 4, '.') * 1;
	RUN;
%MEND read_ednd;
%read_ednd; 

PROC SORT DATA = ednd OUT = v.ednd NODUPKEY;
	BY company_id executive_id2 fy_end;
RUN;

* Read in Option Awards - ND;
%MACRO read_option_awards;
	%DO year = 2006 %TO 2016;
		PROC IMPORT DATAFILE = "[redacted-path-b8bd76a092ed]" 
			OUT = oand_&year
			DBMS = EXCELCS
			REPLACE; 
			SHEET = "Option Award Details - ND";
		RUN;

		DATA oand_&year;
			SET oand_&year;
			RENAME 	dividend_yield___ = dividendyield
					stock_price = stockprice
					Grant_Date_Present_Value_of_Opti = GrantDatePresentValueofOpti
					Grant_Date_Present_Value_of_Opt0 = GrantDatePresentValueofOpt0
					Grant_Date_Present_Value_of_Opt1 = GrantDatePresentValueofOpt1
					Grant_Date_Present_Value_of_Opt2 = GrantDatePresentValueofOpt2;

* Read in Stock Awards - ND;
%MACRO read_stock_awards;
	%DO year = 2006 %TO 2016;
		PROC IMPORT DATAFILE = "[redacted-path-b8bd76a092ed]" 
			OUT = sand_&year
			DBMS = EXCELCS
			REPLACE; 
			SHEET = "Stock Award Details - ND";

RUN;

DATA ipand_&year;
	SET ipand_&year;
	equilarfyear = &year; 
	fyear = YEAR(fy_end) - (MONTH(fy_end) <= 5);
	executive_id2 = SCAN(executive_id, 4, '.') * 1;
	FORMAT fy_end grant_date MMDDYY10.; 
	WHERE executive ^= "" AND company_id ^= 9999999;

	%DO year = 2006 %TO 2016;
		PROC IMPORT DATAFILE = "[redacted-path-b8bd76a092ed]" 
			OUT = oend_&year
			DBMS = EXCELCS
			REPLACE; 
			SHEET = "Outstanding Equity - ND";
		RUN;

		DATA oend_&year;
			SET oend_&year;
			DROP _ _1 _2;
			equilarfyear = &year; 
			fyear = YEAR(fy_end) - (MONTH(fy_end) <= 5);
			executive_id2 = SCAN(executive_id, 4, '.') * 1;

			FORMAT fy_end expiration_date MMDDYY10.; 
			WHERE executive ^= "" AND company_id ^= 9999999;
		RUN;
	%END;

	DATA v.oend; 
		SET oend_2015 oend_2006-oend_2014 oend_2016; 
		RENAME 	remaining_term_as_of_fiscal_year = remaining_term
				value_as_of_fiscal_year_end_____ = value
				in_the_money__as_of_fiscal_year_ = in_the_money;
	RUN;
%MEND read_outstanding_equity;
%read_outstanding_equity;

