LIBNAME compna '[redacted-path-ad0205a081b9]'; 

PROC SQL UNDO_POLICY = NONE;
	CREATE TABLE cominfo AS
	SELECT 	gvkey, fyear,  
			cusip AS compcusip, 
			SUBSTR(cusip, 1, LENGTH(cusip) - 1) AS cusip2,
			SUBSTR(cusip, 1, 6) AS cusip6,
			FYR, OPTDR, OPTRFR, OPTVOL, CONM, TIC, 
			datadate, CURCD, prcc_f, ADJEX_C, ADJEX_F, AJEX, AJP, cshpri
	FROM 	compna.funda 
	WHERE	indfmt = 'INDL' AND datafmt = 'STD' AND popsrc = 'D' AND consol = 'C' 
			AND fyear >= 2004; 
QUIT;	

PROC DOWNLOAD DATA = cominfo OUT = cominfo; RUN;
ENDRSUBMIT;

