PROC SQL;
	CREATE TABLE match2 AS
	SELECT	a.*, (b.fy_end ^= .) AS manual
	FROM	match2 a LEFT JOIN match2manual b
	ON		a.gvkey = b.gvkey AND a.fy_end = b.fy_end
	HAVING	namematch OR namematch2 OR cusip6match OR manual;
QUIT;

