* matched;
PROC SQL;
	CREATE TABLE match5verified AS
	SELECT	a.*
	FROM	match5 a,  match5manual b
	WHERE	a.company_id = b.company_id AND a.fy_end = b.fy_end
			AND a.gvkey = b.gvkey;

* some firm-years are flagged as transition years;
DATA cfcomp;
	SET match1-match4 match5verified match6;
	DROP adjex_c adjex_f ajex ajp; 
	diff = ABS(datadate - fy_end);

* Black Scholes assumptions from Equilar, Compustat, ExecuComp;
* BS assumptions from OAND;
DATA bsinputsequilar; 
	SET v.oand (KEEP = fyear company_id fy_end volatility_ risk_free_rate__ dividendyield grant_date);
RUN;

* Keep year t first grant inputs and year t-1 last grant inputs;
PROC SORT DATA = bsinputsequilar; 
	BY company_id fy_end grant_date;
RUN;

* for year t, keep the BS input of the first grant;
DATA bsinputs;
	SET bsinputsequilar; 
	BY company_id fy_end grant_date; 
	IF FIRST.fy_end; 
	DROP grant_date fy_end; 
	RENAME company_id = company_id;
	LABEL company_id = company_id; 
RUN;

* for year t-1, keep the BS input of the last grant;
DATA lagbsinputs;
	SET bsinputsequilar; 
	BY company_id fy_end grant_date; 
	IF LAST.fy_end; 
	DROP grant_date fy_end;
	RENAME 	fyear = lagfyear
			volatility_ = lagvolatility_
			risk_free_rate__ = lagrisk_free_rate__
			dividendyield = lagdividendyield
			company_id = company_id;
RUN;

* ExecuComp & Compustat BS assumptions;
%LET wrds = wrds.wharton.upenn.edu 4016;
OPTIONS COMAMID = TCP REMOTE = wrds; 
SIGNON USERNAME = _PROMPT_;
RSUBMIT;

LIBNAME compna '[redacted-path-ad0205a081b9]'; 
LIBNAME exec '[redacted-path-cd8aebf43f41]';

* B/S assumptions from ExecuComp;
DATA bsinputsexec;
	SET exec.codirfin (KEEP = year gvkey bs_volatility bs_yield);
	bs_yield = bs_yield / 100;
	WHERE year >= 2004;
RUN;

* B/S assumptions from Compustat;
DATA bsinputscomp;
	SET compna.funda (KEEP = gvkey fyear optdr optrfr optvol indfmt datafmt popsrc consol);
	optdr = optdr / 100;
	optrfr = optrfr / 100;
	optvol = optvol / 100;
	DROP indfmt datafmt popsrc consol;
	WHERE indfmt = 'INDL' AND datafmt = 'STD' AND popsrc = 'D' AND consol = 'C' AND fyear >= 2004;
RUN;

* merge the two;
PROC SQL;
	CREATE TABLE bsinputsboth AS
	SELECT	COALESCE(a.gvkey, b.gvkey) AS gvkey,
			COALESCE(a.year, b.fyear) AS fyear,
			bs_volatility, bs_yield,
			optdr, optrfr, optvol
	FROM	bsinputsexec a FULL JOIN bsinputscomp b
	ON		a.gvkey = b.gvkey AND a.year = b.fyear;
QUIT;

