* Merge with CRSP daily stock file and calculate annalized standard deviation of daily return;
PROC SQL;
	CREATE TABLE vol1 AS
	SELECT		gvkey, permno, fyear, 
				COUNT(*) AS n_ret, STD(LOG(1 + ret)) AS std_ret,
				CALCULATED std_ret * SQRT(252) AS annualret
	FROM		permnoindex1 a, crspsd.dsf (KEEP = date permno ret prc) b
	WHERE		a.lpermno = b.permno AND b.date BETWEEN a.lagdatadate - 365 * 3 AND a.lagdatadate
	GROUP BY	gvkey, permno, fyear
	ORDER BY	gvkey, fyear, annualret;
QUIT;
PROC DOWNLOAD DATA = vol1 OUT = vol1; RUN;

ENDRSUBMIT;

* Merge with CRSP daily stock file and calculate annalized standard deviation of daily return;
PROC SQL;
	CREATE TABLE vol2 AS
	SELECT		gvkey, permno, fyear, 
				COUNT(*) AS n_ret, STD(LOG(1 + ret)) AS std_ret,
				CALCULATED std_ret * SQRT(252) AS annualret
	FROM		permnoindex2 a, crspsd.dsf (KEEP = date permno ret prc) b
	WHERE		a.lpermno = b.permno AND b.date BETWEEN a.lagdatadate - 365 * 4 AND a.lagdatadate + 365
	GROUP BY	gvkey, permno, fyear
	ORDER BY	gvkey, fyear, annualret;
QUIT;

PROC DOWNLOAD DATA = vol2 OUT = vol2; RUN;
ENDRSUBMIT;

/*
risk free interest rate source:
v.interestrates_2017:

Data List: Interest Rates
Data Updated: 2017-05-23

FRED (Federal Reserve Economic Data)
Link: https://fred.stlouisfed.org
Help: https://fred.stlouisfed.org/help-faq
Economic Research Division
Federal Reserve Bank of St. Louis
*/

PROC SQL;
	CREATE TABLE filledinterest AS
	SELECT		a.*, b.*
	FROM		gvkeyindex3 a, 
				v.interestrates_2017 (WHERE = (YEAR(date) >= 2004 AND dgs1 ^= .)
				KEEP = date DGS1 DGS10 DGS1MO DGS2 DGS20 DGS3 DGS30 DGS3MO DGS5 DGS6MO DGS7) b
	WHERE		b.date BETWEEN 
				INTNX('MONTH', datadate, -12, 'END') - 5 AND INTNX('MONTH', datadate, -12, 'END')
	GROUP BY	fyear, gvkey, lagterm, datadate
	HAVING		date = MAX(date);
QUIT;

DATA filledinterest; 
	SET filledinterest;
	mindis = MIN(ABS(lagterm - 1), ABS(lagterm - 2), ABS(lagterm - 3), ABS(lagterm - 5), ABS(lagterm - 7),
		ABS(lagterm - 10), ABS(lagterm - 20), ABS(lagterm - 30), ABS(lagterm - 0.083), 
		ABS(lagterm - 0.25), ABS(lagterm - 0.5));
	IF mindis = ABS(lagterm - 1) THEN rfr = DGS1 * 0.01;
	ELSE IF mindis = ABS(lagterm - 2) THEN rfr = DGS2 * 0.01;
	ELSE IF mindis = ABS(lagterm - 3) THEN rfr = DGS3 * 0.01;
	ELSE IF mindis = ABS(lagterm - 5) THEN rfr = DGS5 * 0.01;
	ELSE IF mindis = ABS(lagterm - 7) THEN rfr = DGS7 * 0.01;
	ELSE IF mindis = ABS(lagterm - 10) THEN rfr = DGS10 * 0.01;
	ELSE IF mindis = ABS(lagterm - 20) THEN rfr = DGS20 * 0.01;
	ELSE IF mindis = ABS(lagterm - 30) THEN rfr = DGS30 * 0.01;
	ELSE IF mindis = ABS(lagterm - 0.083) THEN rfr = DGS1MO * 0.01;
	ELSE IF mindis = ABS(lagterm - 0.25) THEN rfr = DGS3MO * 0.01;
	ELSE IF mindis = ABS(lagterm - 0.5) THEN rfr = DGS6MO * 0.01; 
RUN;

LIBNAME compna '[redacted-path-ad0205a081b9]'; 
PROC UPLOAD DATA = gvkeyindex4 OUT = gvkeyindex4; RUN;

* Merge with Compustat to obtain dividend yield;
* use the average of the last 5 years;
PROC SQL;
	CREATE TABLE dividends AS
	SELECT		a.gvkey, a.fyear, 
				AVG(COALESCE(dvpsp_f / prcc_f, dvc / (prcc_f * csho))) AS mean_div
	FROM		gvkeyindex4 a, 
				compna.funda (KEEP = gvkey fyear dvt dv dvc dvpsp_f prcc_f csho
				indfmt datafmt popsrc consol
				WHERE = (indfmt = 'INDL' AND datafmt = 'STD' AND popsrc = 'D' 
				AND consol = 'C' AND fyear >= 1998)) b
	WHERE		a.gvkey = b.gvkey AND b.fyear BETWEEN a.fyear - 5 AND a.fyear - 1
	GROUP BY	a.gvkey, a.fyear
	HAVING		mean_div ^= .;
QUIT;

PROC DOWNLOAD DATA = dividends OUT = dividends; RUN;

* Retrieve all stock awards and calculate their vesting begin and end date;
* Vesting begin date is one year after grant date, vesting end date is vestingperiod year after grant date;
DATA sand;
	SET v.sand (KEEP = company_id executive_id2 fy_end fyear executive company ticker 
		grant_date number_of_securities vesting_schedule vestingPeriod performance_);

	vestingmonth = MONTH(grant_date); vestingday = DAY(grant_date); 

	* for 2/29 situation, since it does not happen every year;
	vestingday2 = vestingday; IF vestingmonth = 2 AND vestingday = 29 THEN vestingday2 = 28; 
	vestingday3 = vestingday; IF vestingmonth = 2 AND vestingday = 29 
		AND vestingperiod / 4 ^= INT(vestingperiod / 4) THEN vestingday3 = 28; 

	* set vesting begin date to be one year after the grant date and end date to be vestingperiod year after grant date;
	vestingbegdate = MDY(vestingmonth, vestingday2, YEAR(grant_date) + 1);
	vestingenddate = MDY(vestingmonth, vestingday3, YEAR(grant_date) + VestingPeriod); 

	FORMAT vestingbegdate vestingenddate MMDDYY10.; 

	DROP vestingday2 vestingday3;

	IF grant_date ^= .;
	WHERE vesting_schedule ^= "Retirement";
RUN;

