LIBNAME crspa '[redacted-path-b44a419929cd]'; 

PROC SQL UNDO_POLICY = NONE;
	CREATE TABLE mprice AS
	SELECT 		permno, date, prc, shrout, cfacpr, cfacshr
	FROM 		crspa.msf 
	WHERE		YEAR(date) >= 2005
	ORDER BY	permno, date, prc DESC; 
QUIT;	

PROC DOWNLOAD DATA = mprice OUT = mprice; RUN;
ENDRSUBMIT;

* datadate is the month end and lagdatadate is the last month end;
PROC SQL;
	CREATE TABLE mallp AS
	SELECT	a.*, ABS(b.prc) AS prc, ABS(c.prc) AS lagprc, 
			b.cfacpr, b.cfacshr, c.cfacpr AS cfacpr_lag, c.cfacshr AS cfacshr_lag
	FROM	mall a LEFT JOIN mprice b
	ON		a.lpermno = b.permno AND a.datadate = INTNX('MONTH', b.date, 0, 'END')
			LEFT JOIN mprice c
	ON		a.lpermno = c.permno AND a.lagdatadate = INTNX('MONTH', c.date, 0, 'END');
QUIT;

PROC SORT DATA = mallp NODUPKEY; 
	BY gvkey executive_id2 datadate;
RUN;

* adjust the price when lagprc is missing (so we have to use prc) and then the cumulative adjustment factor changed;
DATA v.mallp;
	SET mallp;
	IF prc ^= . AND lagprc = . AND 
			(cfacpr ^= cfacpr_lag AND cfacpr_lag ^= . OR cfacshr ^= cfacshr_lag AND cfacshr_lag ^= .) 
		THEN prc = prc * (cfacshr_lag / cfacshr);
	DROP cfacpr cfacshr cfacpr_lag cfacshr_lag;
RUN;

* Merge diff versions of option vesting schedule with monthly index;
%MACRO newlyvesting_m (var1, var2, var3);

	* vesting options on grant level, define exact vesting date;
	DATA vestingoptions_&var1; 
		SET post2006vestingoptions_&var1;
		lagfy_end = INTNX('MONTH', fy_end, -12, 'END');
		vestingyear = YEAR(fy_end) - (vestingmonth > MONTH(fy_end));
		IF vestingmonth = 2 AND vestingday = 29 AND vestingyear / 4 ^= INT(vestingyear / 4) THEN vestingday = 28;
		vestingtime = MDY(vestingmonth, vestingday, vestingyear);
		FORMAT lagfy_end vestingtime MMDDYY10.; 
		DROP vestingyear vestingmonth vestingday;
		WHERE vestedoptions > 0; 
	RUN;

	* merge vesting options with their BS assumptions;
	PROC SQL;
		CREATE TABLE mallpoptionsbs_&var3 AS
		SELECT	a.*, b.expdate, b.stkprc, b.vestedoptions,
				b.term AS oldterm, b.vestingtime,
				(b.expdate - datadate) / 365 AS term,
				CALCULATED term + 0.25 AS lagterm,
				c.*
		FROM 	mallpshares_&var2 a LEFT JOIN vestingoptions_&var1 b
		ON		a.company_id = b.company_id AND a.executive_id2 = b.executive_id2 AND a.fy_end = b.fy_end
				AND b.vestingtime BETWEEN a.lagdatadate + 1 AND a.datadate
				LEFT JOIN bsassumptions c
		ON		a.company_id = c.company_id AND a.fy_end = c.fy_end AND a.executive_id2 = c.executive_id2
				AND b.expdate = c.expdate AND b.stkprc = c.stkprc AND b.vestedoptions = c.vestedoptions;
	QUIT;

	* Calculate value of newly vested options;
	* Calculate Z, Delta, and Option values;
	DATA mallpoptionsbs_cal_&var3; 
		SET mallpoptionsbs_&var3;
		IF lagterm > 0 AND stkprc > 0 AND finalvol1 ^= 0 THEN DO;
			Z1 = (LOG(lagprc / stkprc) + lagterm * (finalrfr1 - finaldivyield1 + finalvol1**2 / 2)) / (finalvol1 * SQRT(lagterm));

			IF lagprc = . AND prc ^= . THEN DO;
				Z1 = (LOG(prc / stkprc) + lagterm * (finalrfr1 - finaldivyield1 + finalvol1**2 / 2)) / (finalvol1 * SQRT(lagterm));
			END;

			delta1_un = EXP(-finaldivyield1 * lagterm) * CDF("NORMAL", Z1);

			delta1 = EXP(-finaldivyield1 * lagterm) * CDF("NORMAL", Z1) * vestedoptions;
		END;
		* For v2, assume delta is replaced with their intrinsic value;
		%IF &var3 = v2 %THEN %DO;
			delta1_un = (stkprc <= lagprc);
			delta1 = delta1_un * vestedoptions;
		%END;

		* For v3, assume all options are at the money;
		%IF &var3 = v3 %THEN %DO;
			IF lagterm > 0 AND finalvol1 ^= 0 THEN DO;			
				Z1 = (LOG(1) + lagterm * (finalrfr1 - finaldivyield1 + finalvol1**2 / 2)) / (finalvol1 * SQRT(lagterm));

				delta1_un = EXP(-finaldivyield1 * lagterm) * CDF("NORMAL", Z1);

				delta1 = EXP(-finaldivyield1 * lagterm) * CDF("NORMAL", Z1) * vestedoptions;
			END;
		%END;
	RUN;

