* Match TFN with Equilar Exeuctives;
* match insider trading with MM using 6-digit cusip;
PROC SQL;
	CREATE TABLE cusip_match AS
	SELECT		company_id, executive_id2, fy_end, lagfy_end, cusip, cusip6, 
				conm, company_name, cname, personid, executive, owner, rolecode1
	FROM		v.mm (WHERE = (lagexist = 1)) a, insider_table1 b
	WHERE		SUBSTR(cusip, 1, 6) = cusip6 AND cusip6 ^= '' AND
				b.trandate BETWEEN a.lagfy_end AND a.fy_end;
QUIT;
PROC SORT DATA = cusip_match NODUPKEY;
	BY company_id executive_id2 fy_end lagfy_end cusip executive cusip6
		conm company_name personid owner;
RUN;

* Classify these matches;
* Perfect matches without dupkey;
DATA namematch;
	SET cusip_match2;
	IF match1 AND match2 OR match1 AND match3;
RUN;

PROC SQL;
	CREATE TABLE namematch_nodupkey AS
	SELECT		*, COUNT(*) AS n_personid
	FROM		namematch
	GROUP BY	executive_id2, fy_end
	HAVING		COUNT(*) = 1;
QUIT;

* Perfect matches BUT with dupkey;
PROC SQL;
	CREATE TABLE namematch_dupkey AS
	SELECT		lagfy_end, cusip, cusip6, conm, company_name, cname, personid, company_id,
				executive_id2, fy_end, executive, owner, rolecode1, match1, match2, match3
	FROM		namematch
	WHERE		executive_id2 NOT IN (SELECT UNIQUE executive_id2 FROM namematch_nodupkey)
	ORDER BY	company_id, executive_id2, fy_end, personid;
QUIT;
DATA namematch_dupkey;
	SET namematch_dupkey;
	new = (company_id ^= LAG(company_id) OR fy_end ^= LAG(fy_end));
RUN;

PROC EXPORT DATA = namematch_dupkey
	OUTFILE = "[redacted-path-951840ebab78]" REPLACE
	DBMS = EXCELCS; 
	SHEET = "namematch_dupkey";
RUN;

* Non perfect matches;
