* Read in RA collected files and clean them;
%MACRO read_monthly_rp;
	%DO i = 1 %TO 10;
		PROC IMPORT DATAFILE = "[redacted-path-67597e3735ba]" 
			OUT = monthly_rp_&i._of_10
			DBMS = XLSX
			REPLACE; 
		RUN;

		DATA monthly_rp_clean_&i._of_10;
			SET monthly_rp_&i._of_10;
			%IF &i ^= 6 %THEN %DO;
				monthly_repurchase2 = INPUT(monthly_repurchase, 8.);
				DROP monthly_repurchase;
				RENAME monthly_repurchase2 = monthly_repurchase;

				avg_price_paid_per_share2 = INPUT(avg_price_paid_per_share, 8.);
				DROP avg_price_paid_per_share;
				RENAME avg_price_paid_per_share2 = avg_price_paid_per_share;
			%END;
			total_program_purchase2 = INPUT(total_program_purchase, 8.);
			DROP total_program_purchase;
			RENAME total_program_purchase2 = total_program_purchase;
			file_num = &i;
			WHERE cik IS NOT MISSING AND month_number IS NOT MISSING;
		RUN;
	%END;

	* aggregate them, only keep relevant variables;
	* define repurchase month variable;
	DATA monthly_rp_collected;
		SET %DO i = 1 %TO 10; monthly_rp_clean_&i._of_10 %END;;
		repurchase_monthend = INTNX('MONTH', compustat_date, month_number - 3, 'E');
		FORMAT repurchase_monthend YYMMDD10.;
		repurchase_month = YEAR(repurchase_monthend) * 100 + MONTH(repurchase_monthend);
		KEEP cik compustat_date qtr_repurchase monthly_repurchase avg_price_paid_per_share repurchase_monthend repurchase_month file_num;
	RUN;
%MEND;
