PROC SQL;
	CREATE TABLE repurchase_m2 AS
	SELECT	a.*, c.*
	FROM	repurchase_m2 a LEFT JOIN compustat_crsp_link b
	ON		a.gvkey = b.gvkey  
			AND a.monthend >= b.linkdt AND (a.monthend <= b.linkenddt OR b.linkenddt = .E)
			LEFT JOIN crsp_monthly c
