	ORDER BY gvkey, monthend;
QUIT;

* Define monthly repurchase variables;
DATA v.repurchase_m;
	SET repurchase_m2;
	* did not manually collect information of these firms;
	IF cshopq <= 0 THEN DO;
		rpm = 0;
		rpvalpctm = 0;
	END;
	* scale variables by 1000000 because of scale differences in Compustat and CRSP;
	ELSE DO;
		rpm = (monthly_repurchase > 0 OR avg_price_paid_per_share > 0 AND monthly_repurchase = 0);
		* use the # of share and price from Compustat if missing shrout;
		rpvalpctm = (COALESCE(monthly_repurchase * avg_price_paid_per_share, 0) / 1000000) / COALESCE(shrout * prc / 1000, lagcshoq * lagprccq);
	END;
	KEEP gvkey datadate fyearq fqtr fmonth monthend monthly_repurchase avg_price_paid_per_share
		rpm rpvalpctm;
RUN;

