%MACRO BHARmkt (v, date1, date2);
	%IF &v = n3_n2 OR &v = n2_n1 OR &v = n1_0 %THEN %LET month = 1;
	%IF &v = 0_12 OR &v = 12_24 OR &v = 24_36 OR &v = 36_48 OR &v = 48_60 %THEN %LET month = 12;

	PROC SQL;
		CREATE TABLE bharmkt_m&v AS
		SELECT		a.*, b.date, 
					prc * vol AS marketcap,
					EXP(SUM(LOG(1 + ret))) - 1 AS rret&v,
					EXP(SUM(LOG(1 + vwretd))) - 1 AS rvwretd&v,
					SUM(ret - vwretd) AS vwcar&v,
					CALCULATED rret&v - CALCULATED rvwretd&v AS rvwexcessret&v
		FROM		gvkeyindexpermno_bharmkt_m (KEEP = gvkey lpermno monthend &date1 &date2) a,
					crspm.msf (KEEP = date permno ret prc vol WHERE = (ret NOT IN (., .C, .B))) b,
					crspm.msi (KEEP = date vwretd ewretd WHERE = (vwretd ^= . AND ewretd ^= .)) c
		WHERE		a.lpermno = b.permno AND b.date BETWEEN a.&date1 + 1 AND a.&date2
					AND b.date = c.date
		GROUP BY	gvkey, monthend, &date1, &date2, lpermno
		HAVING		date = MAX(date) AND COUNT(ret) = &month
		ORDER BY	gvkey, monthend, &date1, &date2, marketcap DESC;
	QUIT;

