%MACRO MAcar;
	* retrieve daily returns;
	PROC SQL;
		CREATE TABLE ma_acquiror_car AS
		SELECT		a.*, b.date, ret, ret - vwretd AS mar
		FROM		ma_acquiror_permnodate a,
					crsp.dsf (KEEP = date permno ret 
						WHERE = (date BETWEEN MDY(12, 1, 2005) AND MDY(1, 31, 2017)
							AND ret NOT IN (., .C, .B))) b,
					crsp.dsi (KEEP = date vwretd  
						WHERE = (date BETWEEN MDY(12, 1, 2005) AND MDY(1, 31, 2017)
							AND vwretd ^= .)) c
		WHERE		a.permno = b.permno AND ABS(a.anndate - b.date) < 21 AND b.date = c.date
		ORDER BY	permno, anndate, date DESC;
	QUIT;

	* for POST announcement window;
	DATA ma_acquiror_car;
		SET ma_acquiror_car;
		BY permno anndate DESCENDING date;
		ret0 = ret;
		mar0 = mar;
		%DO i = 1 %TO 1;
			ret&i = LAG&i(ret);
			mar&i = LAG&i(mar);
		%END;
		%DO i = 1 %TO 1;
			IF permno = LAG&i(permno) AND anndate = LAG&i(anndate) THEN DO;
				ret0&i = (1 + ret) %DO j = 1 %TO &i; * (1 + ret&j) %END; - 1;
				mar0&i = (1 + mar0) %DO j = 1 %TO &i; * (1 + mar&j) %END; - 1;
				car0&i = SUM(mar0 %DO j = 1 %TO &i; ,mar&j %END;);
			END;
		%END;
	RUN;

	* for PRE announcement window;
	PROC SORT DATA = ma_acquiror_car;
		BY permno anndate date;
	RUN;

	DATA ma_acquiror_car;
		SET ma_acquiror_car;
		BY permno anndate date;
		%DO i = 1 %TO 1;
			ret_lag&i = LAG&i(ret);
			mar_lag&i = LAG&i(mar);
		%END;
		* calculate (-i, i);
		%DO i = 1 %TO 1;
			IF permno = LAG&i(permno) AND anndate = LAG&i(anndate) THEN DO;
				ret_&i.&i = (1 + ret0&i) %DO j = 1 %TO &i; * (1 + ret_lag&j) %END; - 1;
				mar_&i.&i = (1 + mar0&i) %DO j = 1 %TO &i; * (1 + mar_lag&j) %END; - 1;
				car_&i.&i = SUM(car0&i %DO j = 1 %TO &i; ,mar_lag&j %END;);
			END;
		%END;
		DROP ret_lag1 mar_lag1 ret ret1 mar mar1;
	RUN;

	DATA ma_acquiror_car;
		SET ma_acquiror_car (WHERE = (date >= anndate));
		BY permno anndate date;
		IF FIRST.anndate;
	RUN;

	PROC DOWNLOAD DATA = ma_acquiror_car OUT = v.ma_acquiror_car; RUN;
%MEND MAcar;
