* RP;
PROC UPLOAD DATA = rpann_permnodate OUT = rpann_permnodate; RUN;

* retrieve stock price 90 days prior to RP announcement;
* shrout is in thousands;
PROC SQL; 
	CREATE TABLE rpann_mve AS
	SELECT		a.*, ABS(prc * shrout) * 1000 AS mve
	FROM		rpann_permnodate a,
				crsp.dsf (KEEP = date permno prc shrout) b
	WHERE		a.permno = b.permno AND a.anndate - b.date >= 90 AND prc ^= . AND shrout ^= .
	GROUP BY	a.permno, anndate, cusip
	HAVING		date = MAX(date)
	ORDER BY	cusip, anndate, mve DESC;
QUIT;

DATA rpann_mve;
	SET rpann_mve;
	BY cusip anndate DESCENDING mve;
	IF FIRST.anndate;
RUN;

PROC DOWNLOAD DATA = rpann_mve OUT = rpann_mve; RUN;

* MA;
PROC UPLOAD DATA = ma_permnodate OUT = ma_permnodate; RUN;

* retrieve MVE at least 90 days prior to the MA announcement;
* shrout is in thousands;
PROC SQL; 
	CREATE TABLE ma_mve AS
	SELECT		a.*, ABS(prc * shrout) * 1000 AS mve
	FROM		ma_permnodate a,
				crsp.dsf (KEEP = date permno prc shrout) b
	WHERE		a.permno = b.permno AND a.anndate - b.date >= 90 AND prc ^= . AND shrout ^= .
	GROUP BY	a.permno, anndate, cusip
	HAVING		date = MAX(date)
	ORDER BY	cusip, anndate, mve DESC;
QUIT;

DATA ma_mve;
	SET ma_mve;
	BY cusip anndate DESCENDING mve;
	IF FIRST.anndate;
RUN;

