* Aggregate insider selling in the pre- and post- window;
* assign trading day;
DATA trading_days;
	SET trading_days;
	IF _n_ = 1 THEN trading_day_count = 0;
	trading_day_count + 1;
RUN;

PROC SQL;
	CREATE TABLE ma_mve AS
	SELECT		a.*, b.trading_day_count
	FROM		ma_mve a LEFT JOIN trading_days b
	ON			a.anndate BETWEEN b.date - 7 AND b.date
	GROUP BY	cusip, anndate
	HAVING		b.date = MAX(b.date);
QUIT;

PROC SQL;
	CREATE TABLE rpann_mve AS
	SELECT		a.*, b.trading_day_count
	FROM		rpann_mve a LEFT JOIN trading_days b
	ON			a.anndate BETWEEN b.date - 7 AND b.date
	GROUP BY	cusip, anndate
	HAVING		b.date = MAX(b.date);
QUIT;

PROC SQL;
	CREATE TABLE sharesold AS
	SELECT		a.*, b.trading_day_count
	FROM		sharesold a LEFT JOIN trading_days b
	ON			trandate BETWEEN b.date - 7 AND b.date
	GROUP BY	a.cusip6, personid, trandate
	HAVING		b.date = MAX(b.date);
QUIT;

%MACRO sharesold_pre_post;
	%LET window1 = 2;
	%LET window2 = 5;
	%LET window3 = 10;
	%LET window4 = 15;
	%LET window5 = 20;
	%LET window_number = 5;
	%DO w = 1 %TO &window_number;	
		* match repurchase with the insider trading in the pre- and post- window;
		PROC SQL;
			CREATE TABLE rp_sharesold_&&window&w..day AS
			SELECT		cusip, anndate, personid, trandate, 
						sharesoldval, sharesoldval / MVE * 100 AS sharesoldpct,
						(trandate - anndate < 0) AS pre_rpann,
						(trandate - anndate > 0) AS post_rpann
			FROM		(SELECT UNIQUE cusip, anndate, mve, trading_day_count FROM rpann_mve) a, 
						sharesold b
			WHERE		a.cusip = b.cusip6 AND ABS(a.trading_day_count - b.trading_day_count) <= &&window&w;
		QUIT;

%MACRO sharesold_pre_post;
	%LET window1 = 2;
	%LET window2 = 5;
	%LET window3 = 10;
	%LET window4 = 15;
	%LET window5 = 20;
	%LET window_number = 5;
	%DO w = 1 %TO &window_number;	
		* match repurchase with the insider trading in the pre- and post- window;
		PROC SQL;
			CREATE TABLE rp_sharesold_&&window&w..day AS
			SELECT		cusip, anndate, personid, trandate, 
						sharesoldval, sharesoldval / MVE * 100 AS sharesoldpct,
						(trandate - anndate < 0) AS pre_rpann,
						(trandate - anndate > 0) AS post_rpann
			FROM		(SELECT UNIQUE cusip, anndate, mve, trading_day_count FROM rpann_mve) a, 
						sharesold b
			WHERE		a.cusip = b.cusip6 AND ABS(a.trading_day_count - b.trading_day_count) <= &&window&w;
		QUIT;

		* calculate insider trading intensity in the pre- and post- window;
		PROC SQL;
			CREATE TABLE rp_sharesold_&&window&w..day AS
			SELECT		a.*, 
						SUM(b1.sharesoldval) > 0 AS stocksold_dummy_pre&&window&w..day,
						COUNT(UNIQUE b1.personid) AS stocksold_pcount_pre&&window&w..day,
						COUNT(UNIQUE b1.trandate) AS stocksold_dcount_pre&&window&w..day,
						COALESCE(SUM(b1.sharesoldval), 0) AS stocksoldval_total_pre&&window&w..day,
						COALESCE(SUM(b1.sharesoldpct), 0) AS stocksoldpct_total_pre&&window&w..day,
						SUM(b2.sharesoldval) > 0 AS stocksold_dummy_post&&window&w..day,
						COUNT(UNIQUE b2.personid) AS stocksold_pcount_post&&window&w..day,
						COUNT(UNIQUE b2.trandate) AS stocksold_dcount_post&&window&w..day,
						COALESCE(SUM(b2.sharesoldval), 0) AS stocksoldval_total_post&&window&w..day,
						COALESCE(SUM(b2.sharesoldpct), 0) AS stocksoldpct_total_post&&window&w..day
			FROM		(SELECT UNIQUE cusip, anndate FROM rpann_mve) a 
						LEFT JOIN rp_sharesold_&&window&w..day (WHERE = (pre_rpann = 1)) b1
			ON			a.cusip = b1.cusip AND a.anndate = b1.anndate
						LEFT JOIN rp_sharesold_&&window&w..day (WHERE = (post_rpann = 1)) b2
			ON			a.cusip = b2.cusip AND a.anndate = b2.anndate
			GROUP BY	a.cusip, a.anndate;
		QUIT;

		* winsorize the continuous variables;
		%winsorize(
				var = 		stocksoldval_total_pre&&window&w..day stocksoldpct_total_pre&&window&w..day
							stocksoldval_total_post&&window&w..day stocksoldpct_total_post&&window&w..day,
				var_out = 	stocksoldval_total_pre&&window&w..day stocksoldpct_total_pre&&window&w..day
							stocksoldval_total_post&&window&w..day stocksoldpct_total_post&&window&w..day,
				by_var = , 
				left = 1, 
				right = 99, 
				input = rp_sharesold_&&window&w..day,
				output = rp_sharesold_&&window&w..day);

		* match MA with the insider trading in the pre- and post- window;
		PROC SQL;
			CREATE TABLE ma_sharesold_&&window&w..day AS
			SELECT		cusip, anndate, personid, trandate, 
						sharesoldval, sharesoldval / mve * 100 AS sharesoldpct,
						(trandate - anndate < 0) AS pre_ma,
						(trandate - anndate > 0) AS post_ma
			FROM		(SELECT UNIQUE cusip, anndate, mve, trading_day_count FROM ma_mve) a, 
						sharesold b
			WHERE		a.cusip = b.cusip6 AND ABS(a.trading_day_count - b.trading_day_count) <= &&window&w;
		QUIT;

		* calculate insider trading intensity in the pre- and post- window;
		PROC SQL;
			CREATE TABLE ma_sharesold_&&window&w..day AS
			SELECT		a.*, 
						SUM(b1.sharesoldval) > 0 AS stocksold_dummy_pre&&window&w..day,
						COUNT(UNIQUE b1.personid) AS stocksold_pcount_pre&&window&w..day,
						COUNT(UNIQUE b1.trandate) AS stocksold_dcount_pre&&window&w..day,
						COALESCE(SUM(b1.sharesoldval), 0) AS stocksoldval_total_pre&&window&w..day,
						COALESCE(SUM(b1.sharesoldpct), 0) AS stocksoldpct_total_pre&&window&w..day,
						SUM(b2.sharesoldval) > 0 AS stocksold_dummy_post&&window&w..day,
						COUNT(UNIQUE b2.personid) AS stocksold_pcount_post&&window&w..day,
						COUNT(UNIQUE b2.trandate) AS stocksold_dcount_post&&window&w..day,
						COALESCE(SUM(b2.sharesoldval), 0) AS stocksoldval_total_post&&window&w..day,
						COALESCE(SUM(b2.sharesoldpct), 0) AS stocksoldpct_total_post&&window&w..day
			FROM		(SELECT UNIQUE cusip, anndate FROM ma_mve) a 
						LEFT JOIN ma_sharesold_&&window&w..day (WHERE = (pre_ma = 1)) b1
			ON			a.cusip = b1.cusip AND a.anndate = b1.anndate
						LEFT JOIN ma_sharesold_&&window&w..day (WHERE = (post_ma = 1)) b2
			ON			a.cusip = b2.cusip AND a.anndate = b2.anndate
			GROUP BY	a.cusip, a.anndate;
		QUIT;

		* winsorize the continuous variables;
		%winsorize(
				var = 		stocksoldval_total_pre&&window&w..day stocksoldpct_total_pre&&window&w..day
							stocksoldval_total_post&&window&w..day stocksoldpct_total_post&&window&w..day,
				var_out = 	stocksoldval_total_pre&&window&w..day stocksoldpct_total_pre&&window&w..day
							stocksoldval_total_post&&window&w..day stocksoldpct_total_post&&window&w..day,
				by_var = , 
				left = 1, 
				right = 99, 
				input = ma_sharesold_&&window&w..day,
				output = ma_sharesold_&&window&w..day);

	%END;

	* merge all RP windows together;
	PROC SQL;
		CREATE TABLE rp_sharesold_allwindow AS
		SELECT	*
		FROM	%DO i = 1 %TO &window_number-1; rp_sharesold_&&window&i..day a&i, %END;
				rp_sharesold_&&window&window_number..day a&window_number
		WHERE	a1.cusip = a2.cusip AND a1.anndate = a2.anndate
				%DO i = 3 %TO &window_number; 
					AND a1.cusip = a&i..cusip AND a1.anndate = a&i..anndate
				%END;;
	QUIT;

	* merge all MA windows together;
	PROC SQL;
		CREATE TABLE ma_sharesold_allwindow AS
		SELECT	*
		FROM	%DO i = 1 %TO &window_number-1; ma_sharesold_&&window&i..day a&i, %END;
				ma_sharesold_&&window&window_number..day a&window_number
		WHERE	a1.cusip = a2.cusip AND a1.anndate = a2.anndate
				%DO i = 3 %TO &window_number; 
					AND a1.cusip = a&i..cusip AND a1.anndate = a&i..anndate
				%END;;
	QUIT;
%MEND sharesold_pre_post;
%sharesold_pre_post;

* merge with newlyvesting and firm-year;
PROC SQL;
	CREATE TABLE rp_sharesold_allwindow_m AS
	SELECT	a.*, 
			stocksoldpct_total_post20day - stocksoldpct_total_pre20day AS stocksoldpct_total_diff20day,
			b.*
	FROM	rp_sharesold_allwindow a, 
			(SELECT		cusip6, datadate, lagdatadate, SUM(newlyvesting) AS newlyvesting
			FROM 		vesting_month 
			GROUP BY	cusip6, datadate, lagdatadate) b
	WHERE	a.cusip = b.cusip6 AND a.anndate BETWEEN b.lagdatadate + 1 AND b.datadate;
QUIT;

PROC EXPORT DATA = rp_sharesold_allwindow_m
	OUTFILE = '[redacted-path-0cb11a33b262]' 
	REPLACE;
RUN;

PROC SQL;
