/* merge with delisting return */

PROC SQL;
	CREATE TABLE crsp_m AS
	SELECT	a.*, 
			b.dlret, b.dlstcd
	FROM	crsp_m a LEFT JOIN crspa.dsedelist b
	ON		a.permno = b.permno AND a.date = INTNX("MONTH",b.dlstdt,0,"E");
QUIT;
